param([switch]$KeepContainer)
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '\..\..'));$c='nello_clinical_attachments_test'
$m=@('20260813040000_d1_d5_clinical_science.sql','20260813041000_d6_d7_meal_plan_integrity.sql','20260813042000_d8_d9_plan_template_versioning.sql','20260813043000_d10_meal_plan_documents.sql','20260813044000_d_advisor_hardening.sql','20260813045000_c8_d_text_encoding_repair.sql','20260813050000_d_scientific_source_url_repair.sql')|%{Join-Path $root "supabase\migrations\$_"};$t=Join-Path $root 'supabase\tests\d1_d10_clinical_prescription_matrix.sql'
try{& (Join-Path $PSScriptRoot 'verify-c8-privacy-requests.ps1') -KeepContainer;if($LASTEXITCODE -ne 0){throw 'C8 regression failed'};for($i=0;$i -lt $m.Count;$i++){docker cp $m[$i] "${c}:/tmp/d-$i.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql --single-transaction -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f "/tmp/d-$i.sql"|Out-Null;if($LASTEXITCODE -ne 0){throw "D migration $i failed"}};docker cp $t "${c}:/tmp/d-matrix.sql"|Out-Null;docker exec -e PGPASSWORD=postgres $c psql -v ON_ERROR_STOP=1 -U supabase_admin -d postgres -f /tmp/d-matrix.sql;if($LASTEXITCODE -ne 0){throw 'D matrix failed'};Write-Output 'D1-D10 clinical and prescription matrix approved.'}finally{if(-not $KeepContainer){docker rm -f $c 2>$null|Out-Null}}
